-- =====================================================================
-- Session 503b migration — canon / Matthew — the RE-POINT pass. 7 card(s) whose old note meant 1 John but whose target was the gospel of John
-- re-pointed to the 1 John verse (target_verse_id UPDATE; id, source verse, thread kept; note and member note rewritten Come-and-See to the new pair):
-- 3675 Matthew 19:16 John 2:3 → 1 John 2:3; 3815 Matthew 21:28 John 2:3 → 1 John 2:3; 3806 Matthew 21:21 John 5:14 → 1 John 5:14; 3912 Matthew 22:40 John 4:7 → 1 John 4:7; 3913 Matthew 22:40 John 5:2 → 1 John 5:2; 4009 Matthew 24:9 John 2:18 → 1 John 2:18; 4109 Matthew 25:41 John 3:16 → 1 John 3:16.
-- 2 shorthand twin(s) rewritten in place with the target unchanged: 3013 Matthew 26:64 → Mark 14:62, 120012 Matthew 6:14 → Mark 11:25.
-- Written and read on Claude Fable 5.1 against the read-back live read-back S503 (canon/matthew) · schema 1.0.0-phase4-session475. Every note composed by script (build503b.py): target verse whole
-- from parsed/canon.json, Matthew verse whole from the live text, then the prose.
-- Safety (DO block, before any write): RAISES if a card is gone, if it sits neither on its old pair with its old note nor already on its new pair with
-- its new note, if its Matthew live text moved, if its member row is missing or carries neither member note, or if another card already holds the
-- new pair. Idempotent: a re-run reports 0 everywhere. Nothing deleted, no card added.
-- Run: python3 api/apply_migration.py data-schema/migrations/session503b_matthew_repoint.sql
-- =====================================================================
\echo 'session503b — Matthew re-point pass starting...'
BEGIN;
CREATE TEMP TABLE _s503b_c (id BIGINT, src_ch INT, src_v INT, src_text TEXT, o_ed TEXT, o_book TEXT, o_ch INT, o_v INT, n_ed TEXT, n_book TEXT, n_ch INT, n_v INT, src TEXT, old_note TEXT, new_note TEXT, thread_id BIGINT, old_mnote TEXT, new_mnote TEXT) ON COMMIT DROP;
INSERT INTO _s503b_c VALUES
(3675,19,16,$n$And, behold, one came and said unto him, Good Master, what good thing shall I do, that I may have eternal life?$n$,'canon','john',2,3,'canon','1-john',2,3,'manual',$n$John 2:3 — *And when they wanted wine, the mother of Yahusha (Jesus) saith unto him, They have no wine.* *And, behold, one came and said unto him, Good Master, what good thing shall I do, that I may have eternal life?* (Matthew 19:16) The match is in the next verse, not this one. At Cana his mother tells the servants *Whatsoever he saith unto you, do it* (John 2:5), and the young man is asking the same Master what to do. What he says to him is to keep the commandments.$n$,$n$1 John 2:3 — *And hereby we do know that we know him, if we keep his commandments.* *And, behold, one came and said unto him, Good Master, what good thing shall I do, that I may have eternal life?* (Matthew 19:16) The young man asks what good thing he must do to have eternal life, and the answer he gets is *if thou wilt enter into life, keep the commandments* (Matthew 19:17). John says the same thing from the other side: keeping the commandments is how a man knows that he knows him. The question and the test are one. Life is in the knowing, and the knowing shows itself in the keeping.$n$,378,$n$John 2:3 — *And when they wanted wine, the mother of Yahusha (Jesus) saith unto him, They have no wine.* At Cana his mother tells the servants to do whatever he says, as the young man is now told what to do.$n$,$n$1 John 2:3 — *And hereby we do know that we know him, if we keep his commandments.* Keeping his commandments is how we know that we know him: the young man's question answered from John's side.$n$),
(3815,21,28,$n$But what think you? A certain man had two sons; and he came to the first, and said, Son, go work to day in my vineyard.$n$,'canon','john',2,3,'canon','1-john',2,3,'manual',$n$John 2:3 — *And when they wanted wine, the mother of Yahusha (Jesus) saith unto him, They have no wine.* *But what think you? A certain man had two sons; and he came to the first, and said, Son, go work to day in my vineyard.* (Matthew 21:28) What counts at Cana, as in the vineyard, is the doing. His mother says only *They have no wine*, and then tells the servants *Whatsoever he saith unto you, do it* (John 2:5). The parable asks which son did what the father said, and the servants at the wedding are handed the same rule.$n$,$n$1 John 2:3 — *And hereby we do know that we know him, if we keep his commandments.* *But what think you? A certain man had two sons; and he came to the first, and said, Son, go work to day in my vineyard.* (Matthew 21:28) The father says *go work to day in my vineyard*, and the parable turns on which son went. John gives the same measure for the whole house: we know that we know him *if we keep his commandments*. A yes with no going is not the knowing; a refusal followed by going is. The vineyard and John's test ask one thing, who did what the father said.$n$,389,$n$John 2:3 — *And when they wanted wine, the mother of Yahusha (Jesus) saith unto him, They have no wine.* At the wedding in Cana the mother of Yahusha (Jesus) brings him the need, then tells the servants to do whatever he says.$n$,$n$1 John 2:3 — *And hereby we do know that we know him, if we keep his commandments.* We know that we know him if we keep his commandments: the measure the two sons are judged by.$n$),
(3806,21,21,$n$Yahusha (Jesus) answered and said unto them, Verily I say unto you, If you have faith, and doubt not, you shall not only do this which is done to the fig tree, but also if you shall say unto this mountain, Be you removed, and be you cast into the sea; it shall be done.$n$,'canon','john',5,14,'canon','1-john',5,14,'manual',$n$John 5:14 — *Afterward Yahusha (Jesus) findeth him in the temple, and said unto him, Behold, thou art made whole: sin no more, lest a worse thing come unto thee.* *Yahusha (Jesus) answered and said unto them, Verily I say unto you, If you have faith, and doubt not, you shall not only do this which is done to the fig tree, but also if you shall say unto this mountain, Be you removed, and be you cast into the sea; it shall be done.* (Matthew 21:21) In Matthew a word from him withers a tree and moves mountains, and a word of his made a man whole. He finds that man later in the temple and gives a second word, *sin no more, lest a worse thing come unto thee*. What he does by his word comes with a claim on how the man walks afterward.$n$,$n$1 John 5:14 — *And this is the confidence that we have in him, that, if we ask any thing according to his will, he heareth us:* *Yahusha (Jesus) answered and said unto them, Verily I say unto you, If you have faith, and doubt not, you shall not only do this which is done to the fig tree, but also if you shall say unto this mountain, Be you removed, and be you cast into the sea; it shall be done.* (Matthew 21:21) He tells the disciples that faith without doubting moves a mountain into the sea, and goes straight on, *whatsoever ye shall ask in prayer, believing, ye shall receive* (Matthew 21:22). John gives the asking its ground: the thing asked is *according to his will*, and *he heareth us*. The confidence that moves mountains is not in the asker's nerve but in the one who hears, and in asking what he wills.$n$,43285,$n$John 5:14 — *Behold, thou art made whole: sin no more, lest a worse thing come unto thee.* Yahusha (Jesus) finds the healed man in the temple and tells him to sin no more, lest something worse come.$n$,$n$1 John 5:14 — *And this is the confidence that we have in him, that, if we ask any thing according to his will, he heareth us:* Confidence in asking rests on asking according to his will and on the one who hears: the ground under the mountain-moving faith.$n$),
(3912,22,40,$n$On these two commandments hang all the law and the prophets.$n$,'canon','john',4,7,'canon','1-john',4,7,'manual',$n$John 4:7 — *There cometh a woman of Samaria to draw water: Yahusha (Jesus) saith unto her, Give me to drink.* *On these two commandments hang all the law and the prophets.* (Matthew 22:40) At Jacob's well, wearied from the road, Yahusha (Jesus) asks a woman of Samaria for a drink, on the ground Jacob gave to his son Joseph. The second commandment is walked out there: he goes to one the Yahudim (Jews) had no dealings with and asks her for something, as a neighbour would.$n$,$n$1 John 4:7 — *Beloved, let us love one another: for love is of Elohim (God); and every one that loveth is born of Elohim (God), and knoweth Elohim (God).* *On these two commandments hang all the law and the prophets.* (Matthew 22:40) All the law and the prophets hang on two commandments, love of Yahuah (the LORD) and love of neighbour. John shows the two are one cord: whoever loves *is born of Elohim (God)*, and the one so born *knoweth Elohim (God)*. Loving the brother is not a second thing added to knowing the Father; it is where the knowing shows. The two commandments hang together because love is of Elohim (God).$n$,394,$n$John 4:7 — *There cometh a woman of Samaria to draw water: Yahusha (Jesus) saith unto her, Give me to drink.* At the well he asks a woman of Samaria for a drink, the love of neighbour shown to one others kept away from.$n$,$n$1 John 4:7 — *Beloved, let us love one another: for love is of Elohim (God); and every one that loveth is born of Elohim (God), and knoweth Elohim (God).* Every one that loveth is born of Elohim (God) and knoweth him: the two commandments shown as one cord.$n$),
(3913,22,40,$n$On these two commandments hang all the law and the prophets.$n$,'canon','john',5,2,'canon','1-john',5,2,'manual',$n$John 5:2 — *Now there is at Jerusalem by the sheep market a pool, which is called in the Hebrew tongue Bethesda, having five porches.* *On these two commandments hang all the law and the prophets.* (Matthew 22:40) He goes up to Jerusalem at a feast of the Yahudim (Jews) and walks into the porches of Bethesda, where lay *a great multitude of impotent folk* (John 5:3). The two commandments are in one trip, the feast of Yahuah (the LORD) and the sick at the pool.$n$,$n$1 John 5:2 — *By this we know that we love the children of Elohim (God), when we love Elohim (God), and keep his commandments.* *On these two commandments hang all the law and the prophets.* (Matthew 22:40) The two commandments that carry the law and the prophets stand in one sentence of John's: we know we love the children of Elohim (God) *when we love Elohim (God), and keep his commandments*. Love of the brother is proved by love of the Father, and love of the Father is proved by keeping what he said. John hangs the one on the other exactly as Yahusha (Jesus) hangs the law and the prophets on the two.$n$,394,$n$John 5:2 — *Now there is at Jerusalem by the sheep market a pool, which is called in the Hebrew tongue Bethesda, having five porches.* He goes up to Jerusalem for the feast and then to Bethesda, where the blind, lame and withered lay waiting.$n$,$n$1 John 5:2 — *By this we know that we love the children of Elohim (God), when we love Elohim (God), and keep his commandments.* Love of the children of Elohim (God) known by loving him and keeping his commandments: both commandments in one verse.$n$),
(4009,24,9,$n$Then shall they deliver you up to be afflicted, and shall kill you: and you shall be hated of all nations for my name’s sake.$n$,'canon','john',2,18,'canon','1-john',2,18,'manual',$n$John 2:18 — *Then answered the Yahudim (Jews) and said unto him, What sign shewest thou unto us, seeing that thou doest these things?* *Then shall they deliver you up to be afflicted, and shall kill you: and you shall be hated of all nations for my name’s sake.* (Matthew 24:9) Matthew says his people will be handed over, killed, and hated for his name. In John it begins in the temple, where those who answer him ask what sign he shows for driving out the sellers: *What sign shewest thou unto us*. His answer is his own death and rising, *Destroy this temple, and in three days I will raise it up* (John 2:19), so the killing foretold for them was first spoken of him.$n$,$n$1 John 2:18 — *Little children, it is the last time: and as ye have heard that antichrist shall come, even now are there many antichrists; whereby we know that it is the last time.* *Then shall they deliver you up to be afflicted, and shall kill you: and you shall be hated of all nations for my name’s sake.* (Matthew 24:9) Yahusha (Jesus) tells the disciples they will be delivered up, killed and hated of all nations for his name. John, writing when it had begun, names the hour and the enemy: *it is the last time*, and *even now are there many antichrists*. The hatred for his name does not wait for one man at the end of the age; John says the many were already there, and that is how the time is known.$n$,43290,$n$John 2:18 — *Then answered the Yahudim (Jews) and said unto him, What sign shewest thou unto us, seeing that thou doest these things?* The first challenge to him, in the temple, which he answers with the sign of his own death and rising.$n$,$n$1 John 2:18 — *even now are there many antichrists; whereby we know that it is the last time.* Many antichrists already, and by them the last time is known: the hatred for his name begun in John's own day.$n$),
(4109,25,41,$n$Then shall he say also unto them on the left hand, Depart from me, you cursed, into everlasting fire, prepared for the devil and his angels:$n$,'canon','john',3,16,'canon','1-john',3,16,'manual',$n$John 3:16 — *For Elohim (God) so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life.* *Then shall he say also unto them on the left hand, Depart from me, you cursed, into everlasting fire, prepared for the devil and his angels:* (Matthew 25:41) In John the Father *so loved the world, that he gave his only begotten Son*, and in Matthew the hand that gives nothing hears *Depart from me*. The Father's giving is set against the goats' withholding, and *perish* is where that road ends.$n$,$n$1 John 3:16 — *Hereby perceive we the love of Elohim (God), because he laid down his life for us: and we ought to lay down our lives for the brethren.* *Then shall he say also unto them on the left hand, Depart from me, you cursed, into everlasting fire, prepared for the devil and his angels:* (Matthew 25:41) The ones on the left hear *Depart from me*, and the reason follows them: they fed no one, clothed no one, visited no one. John names what they lacked. Love is known because he *laid down his life for us*, and so *we ought to lay down our lives for the brethren*. The goats never laid down anything for the least of his brethren, and that is the whole charge against them.$n$,18,$n$John 3:16 — *For Elohim (God) so loved the world, that he gave his only begotten Son.* The Father gave his Son, set against the hand that gave nothing, which hears depart from me.$n$,$n$1 John 3:16 — *Hereby perceive we the love of Elohim (God), because he laid down his life for us: and we ought to lay down our lives for the brethren.* Love known in his laying down his life, and owed to the brethren: what the goats on the left never did.$n$),
(3013,26,64,$n$Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.$n$,'canon','mark',14,62,'canon','mark',14,62,'manual',$n$The Markan-parallel.$n$,$n$Mark 14:62 — *And Yahusha (Jesus) said, I am: and ye shall see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* *Yahusha (Jesus) says unto him, You have said: nevertheless I say unto you, Hereafter shall you see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* (Matthew 26:64) Matthew hears him answer *Thou hast said*; Mark hears *I am*. Both then give the same two scriptures from his own mouth, the seat at *the right hand of power* and the coming *in the clouds of heaven*: *Sit thou at my right hand* (Psalm 110:1) and Daniel's *one like the Son of Adam came with the clouds of heaven* (Daniel 7:13). Mark's plain *I am* is why the high priest tore his clothes. The claim was understood.$n$,17,$n$The Markan-parallel.$n$,$n$Mark 14:62 — *And Yahusha (Jesus) said, I am: and ye shall see the Son of Adam sitting on the right hand of power, and coming in the clouds of heaven.* Mark's plain I am, with the same right hand and the same clouds in his mouth, at the same question.$n$),
(120012,6,14,$n$For if you forgive men their trespasses, your heavenly Father will also forgive you:$n$,'canon','mark',11,25,'canon','mark',11,25,'manual',$n$*And when ye stand praying, forgive, if ye have ought against any: that your Father also which is in heaven may forgive you your trespasses.* (Mark 11:25) — the same word, joined again to prayer: forgiveness received flows through forgiveness given.$n$,$n$Mark 11:25 — *And when ye stand praying, forgive, if ye have ought against any: that your Father also which is in heaven may forgive you your trespasses.* *For if you forgive men their trespasses, your heavenly Father will also forgive you:* (Matthew 6:14) Matthew sets the rule beside the prayer he has just taught; Mark sets it inside the act of praying, *when ye stand praying, forgive*. The condition is the same in both, your Father's forgiveness bound to yours, and Mark adds the moment it applies: not after prayer and not as a separate duty, but standing there with the request on your lips. The forgiving comes with the asking.$n$,30019,$n$Mark 11:25 — *when ye stand praying, forgive... that your Father also which is in heaven may forgive you* — the same word joined to prayer.$n$,$n$Mark 11:25 — *when ye stand praying, forgive, if ye have ought against any.* Mark sets the same rule in the act of praying: forgive as you stand there asking to be forgiven.$n$);
CREATE OR REPLACE TEMP VIEW _s503b_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id, v.text
  FROM verses v JOIN chapters c ON v.chapter_id = c.id JOIN books b ON c.book_id = b.id JOIN editions e ON b.edition_id = e.id;

DO $s503b$
DECLARE r RECORD; sid BIGINT; oid BIGINT; nid BIGINT; ltext TEXT; cur RECORD; n INT; n_rp INT := 0; n_rp_same INT := 0; n_m INT := 0; n_m_same INT := 0; n_total INT;
BEGIN
  FOR r IN SELECT * FROM _s503b_c LOOP
    SELECT verse_id, text INTO sid, ltext FROM _s503b_lookup WHERE edition_slug = 'canon' AND book_slug = 'matthew' AND chapter_number = r.src_ch AND verse_number = r.src_v;
    IF sid IS NULL THEN RAISE EXCEPTION 'S503b: Matthew %:% missing', r.src_ch, r.src_v; END IF;
    IF ltext <> r.src_text THEN RAISE EXCEPTION 'S503b: live text of Matthew %:% differs from the read-back — re-dump and rebuild', r.src_ch, r.src_v; END IF;
    SELECT verse_id INTO oid FROM _s503b_lookup WHERE edition_slug = r.o_ed AND book_slug = r.o_book AND chapter_number = r.o_ch AND verse_number = r.o_v;
    SELECT verse_id INTO nid FROM _s503b_lookup WHERE edition_slug = r.n_ed AND book_slug = r.n_book AND chapter_number = r.n_ch AND verse_number = r.n_v;
    IF oid IS NULL OR nid IS NULL THEN RAISE EXCEPTION 'S503b: a target verse for card % is missing', r.id; END IF;
    SELECT * INTO cur FROM cross_references WHERE id = r.id;
    IF NOT FOUND THEN RAISE EXCEPTION 'S503b: card % is gone', r.id; END IF;
    IF cur.source_verse_id <> sid THEN RAISE EXCEPTION 'S503b: card % no longer sits on Matthew %:%', r.id, r.src_ch, r.src_v; END IF;
    IF NOT ((cur.target_verse_id = oid AND cur.note IS NOT DISTINCT FROM r.old_note) OR (cur.target_verse_id = nid AND cur.note IS NOT DISTINCT FROM r.new_note)) THEN
      RAISE EXCEPTION 'S503b: card % does not read as written to its old target (nor already as the new card) — re-dump and rebuild', r.id; END IF;
    IF oid <> nid AND EXISTS (SELECT 1 FROM cross_references x WHERE x.id <> r.id AND x.source_verse_id = sid AND x.target_verse_id = nid AND x.source = r.src) THEN
      RAISE EXCEPTION 'S503b: another card already holds the new pair for card %', r.id; END IF;
    SELECT count(*) INTO n FROM cross_reference_thread_members m WHERE m.cross_reference_id = r.id AND m.thread_id = r.thread_id AND (m.member_note IS NOT DISTINCT FROM r.old_mnote OR m.member_note IS NOT DISTINCT FROM r.new_mnote);
    IF n <> 1 THEN RAISE EXCEPTION 'S503b: card % has no member row in thread % carrying the member note this was written against', r.id, r.thread_id; END IF;
    IF EXISTS (SELECT 1 FROM cross_reference_thread_members m WHERE m.cross_reference_id = r.id AND m.thread_id <> r.thread_id) THEN
      RAISE EXCEPTION 'S503b: card % sits in another thread too — re-dump and rebuild', r.id; END IF;
  END LOOP;

  SELECT count(*) INTO n_total FROM _s503b_c;
  UPDATE cross_references x SET target_verse_id = nv.verse_id, note = c.new_note
    FROM _s503b_c c JOIN _s503b_lookup nv ON nv.edition_slug = c.n_ed AND nv.book_slug = c.n_book AND nv.chapter_number = c.n_ch AND nv.verse_number = c.n_v
   WHERE x.id = c.id AND x.note IS NOT DISTINCT FROM c.old_note AND c.old_note IS DISTINCT FROM c.new_note;
  GET DIAGNOSTICS n_rp = ROW_COUNT; n_rp_same := n_total - n_rp;
  UPDATE cross_reference_thread_members m SET member_note = c.new_mnote FROM _s503b_c c
   WHERE m.cross_reference_id = c.id AND m.thread_id = c.thread_id AND m.member_note IS NOT DISTINCT FROM c.old_mnote AND c.old_mnote IS DISTINCT FROM c.new_mnote;
  GET DIAGNOSTICS n_m = ROW_COUNT; n_m_same := n_total - n_m;

  SELECT count(*) INTO n FROM _s503b_c c JOIN cross_references x ON x.id = c.id JOIN _s503b_lookup nv ON nv.edition_slug = c.n_ed AND nv.book_slug = c.n_book AND nv.chapter_number = c.n_ch AND nv.verse_number = c.n_v
   WHERE x.target_verse_id <> nv.verse_id OR x.note IS DISTINCT FROM c.new_note;
  IF n > 0 THEN RAISE EXCEPTION 'S503b: % card(s) do not carry the new target and note', n; END IF;
  RAISE NOTICE 'S503b (matthew re-point) summary: cards re-pointed/rewritten % / already there %; member notes rewritten % / already there %', n_rp, n_rp_same, n_m, n_m_same;
END $s503b$;
COMMIT;
\echo 'session503b — Matthew re-point pass done.'
